update public.fields set verification_status='verified_against_standard', verification_quote='(2) Neubauten und Neuanlagen sind Objekte, die neu errichtet oder neu hergestellt werden. | (3) Wiederaufbauten sind Objekte, bei denen die zerstörten Teile auf noch vorhandenen Bau- oder Anlagenteilen | (4) Erweiterungsbauten sind Ergänzungen eines vorhandenen Objekts. | (5) Umbauten sind Umgestaltungen eines vorhandenen Objekts mit wesentlichen Eingriffen in Konstruktion oder | (6) Modernisierungen sind bauliche Maßnahmen zur nachhaltigen Erhöhung des Gebrauchswertes eines Objekts, | (8) Instandsetzungen sind Maßnahmen zur Wiederherstellung des zum bestimmungsgemäßen Gebrauch | (9) Instandhaltungen sind Maßnahmen zur Erhaltung des Soll-Zustandes eines Objekts. — printed p.6', verification_note='md-verified 2026-09-05 (§2 Abs.2-9, printed p.6) [VC] — the seven enum values map 1:1 onto § 2 Abs. 2 (Neubau/Neuanlage), 3 (Wiederaufbau), 4 (Erweiterungsbau), 5 (Umbau), 6 (Modernisierung), 8 (Instandsetzung), 9 (Instandhaltung); only the defining first line of each Absatz is quoted', verified_at=now() where id='42beb5b4-823c-4727-a43a-6394b101c026' and verification_status not in ('verified_against_standard','corrected');

