update public.fields set verification_status='verified_against_standard', verification_quote='(1) Anrechenbare Kosten sind Teil der Kosten für die Herstellung, den Umbau, die Modernisierung, Instandhaltung oder Instandsetzung von Objekten sowie für die damit zusammenhängenden Aufwendungen. Sie | bei der Ermittlung der anrechenbaren Kosten zugrunde zu legen. Umsatzsteuer, die auf die Kosten von Objekten entfällt, ist nicht Bestandteil der anrechenbaren Kosten. | 2. für die Leistungsbilder der Teile 3 und 4 und der Anlage 1 Nummer 1.2, 1.3 und 1.4.5 nach den anrechenbaren Kosten des Objekts auf der Grundlage der Kostenberechnung oder, sofern keine Kostenberechnung vorliegt, auf der Grundlage der Kostenschätzung, — printed p.7', verification_note='md-verified 2026-09-05 (§4 Abs.1; §6 Abs.1, printed p.7) [VC]', verified_at=now() where id='05195481-5ae0-4b14-9c15-86aef0d578f7' and verification_status not in ('verified_against_standard','corrected');
