update public.fields set verification_status='verified_against_standard', verification_quote='(1) Die Honorartafeln dieser Verordnung w eisen Orientierungswerte aus, die an der Art und dem Umfang der Aufgabe sowie an der Leistung ausgerichtet sind. Die Honorartafeln enthalten für jeden Leistungsbereich Honorarspannen vom Basishonorarsatz bis zum oberen Honorarsatz, gegliedert nach den | (1) Das Honorar richtet sich nach der Vereinbarung, die die Vertragsparteien in Textform treffen. Sofern keine Vereinbarung über die Höhe des Honorars in Textform getroffen wurde, gilt für Grundleistungen der jeweilige Basishonorarsatz als vereinbart, der sich bei der Anwendung der Honorargrundlagen des § 6 ergibt. — printed p.6, p.8', verification_note='md-verified 2026-09-05 (§2a Abs.1; §7 Abs.1, printed p.6, p.8) [VC] — the 0..1 parametrisation of the position inside the Honorarspanne is EKOWAI’s; the Verordnung names only the two ends (Basishonorarsatz / oberer Honorarsatz) and leaves the point free (SR-2 selection)', verified_at=now() where id='9e34a771-a839-4b11-a33c-07445d3ac733' and verification_status not in ('verified_against_standard','corrected');
