update public.fields set verification_status='verified_against_standard', verification_quote='Der Umbau- oder Modernisierungszuschlag ist unter Berücksichtigung des Schwierigkeitsgrads der Leistungen in Textform zu vereinbaren. Die Höhe des Zuschlags auf das Honorar ist in den jeweiligen Honorarregelungen der Leistungsbilder der Teile 3 und 4 und in Anlage 1 Nummer 1.2 geregelt. Sofern keine Vereinbarung in Textform getroffen wurde, gilt ein Zuschlag von 20 Prozent ab einem durchschnittlichen Schwierigkeitsgrad als vereinbart. — printed p.8', verification_note='md-verified 2026-09-05 (§6 Abs.2, printed p.8) [VC] — the 20 % default applies only in the absence of a Textform agreement; the per-Leistungsbild ceilings are §36 Abs.1 (33 %), §36 Abs.2 (50 %), §52 Abs.4 (50 %), §56 Abs.5 (50 %)', verified_at=now() where id='5ffb4d68-e05f-404e-9a21-f75665895133' and verification_status not in ('verified_against_standard','corrected');
