update public.fields set verification_status='verified_against_standard', verification_quote='(1) Der Auftragnehmer kann neben den Honoraren dieser Verordnung auch die für die Ausführung des Auftrags erforderlichen Nebenkosten in Rechnung stellen; ausgenommen sind die abziehbaren Vorsteuern gemäß § 15 Absatz 1 des Umsatzsteuergesetzes in der jeweils geltenden Fassung. Die Vertragsparteien können in Textform vereinbaren, dass abweichend von Satz 1 eine Erstattung ganz oder teilweise ausgeschlossen ist. | (3) Nebenkosten können pauschal oder nach Einzelnachweis abgerechnet werden. Sie sind nach Einzelnachweis abzurechnen, sofern keine pauschale Abrechnung in Textform vereinbart worden ist. — printed p.9, p.10', verification_note='md-verified 2026-09-05 (§14 Abs.1; §14 Abs.3, printed p.9, p.10) [VC]', verified_at=now() where id='8c6fb0c5-c9ba-4cb7-b202-e1e280a2c212' and verification_status not in ('verified_against_standard','corrected');
