update public.fields set verification_status='verified_against_standard', verification_quote='(1) Für Umbauten und Modernisierungen von Gebäuden kann bei einem durchschnittlichen Schwierigkeitsgrad ein Zuschlag gemäß § 6 Absatz 2 Satz 3 bis 33 Prozent auf das ermittelte Honorar in Textform vereinbart werden. — printed p.24', verification_note='md-verified 2026-09-05 (§36 Abs.1, printed p.24) [VC] — "kann ... bis 33 Prozent ... in Textform vereinbart werden" — a ceiling on an agreed surcharge, not a mandatory value (SR-2)', verified_at=now() where id='9e640882-1178-4681-81ce-67ea4adfcc27' and verification_status not in ('verified_against_standard','corrected');
-- HOAI-2021-04 · z_umbau_innenraum_max
