-- ================= HOAI-2021-07 =================
-- HOAI-2021-07 · vereinbarung_textform
update public.fields set verification_status='verified_against_standard', verification_quote='(1) Das Honorar richtet sich nach der Vereinbarung, die die Vertragsparteien in Textform treffen. Sofern keine Vereinbarung über die Höhe des Honorars in Textform getroffen wurde, gilt für Grundleistungen der jeweilige Basishonorarsatz als vereinbart, der sich bei der Anwendung der Honorargrundlagen des § 6 ergibt. — printed p.8', verification_note='md-verified 2026-09-05 (§7 Abs.1, printed p.8) [VC]', verified_at=now() where id='4230b3a1-ff19-4db2-870e-1a0a49e7edd6' and verification_status not in ('verified_against_standard','corrected');
-- HOAI-2021-07 · auftraggeber_verbraucher
update public.fields set verification_status='verified_against_standard', verification_quote='(2) Der Auftragnehmer hat den Auftraggeber, sofern dieser Verbraucher ist, vor Abgabe von dessen verbindlicher Vertragserklärung zur Honorarvereinbarung in Textform darauf hinzuweisen, dass ein höheres oder niedrigeres Honorar als die in den Honorartafeln dieser Verordnung enthaltenen Werte vereinbart werden kann. Erfolgt der Hinweis nach Satz 1 nicht oder nicht rechtzeitig, gilt für die zwischen den Vertragsparteien vereinbarten Grundleistungen anstelle eines höheren Honorars ein Honorar in Höhe des jeweiligen Basishonorarsatzes als vereinbart. — printed p.8', verification_note='md-verified 2026-09-05 (§7 Abs.2, printed p.8) [VC]', verified_at=now() where id='20ce7622-385d-4d31-8695-edf1d33c8f10' and verification_status not in ('verified_against_standard','corrected');
-- HOAI-2021-07 · hinweis_erteilt
update public.fields set verification_status='verified_against_standard', verification_quote='(2) Der Auftragnehmer hat den Auftraggeber, sofern dieser Verbraucher ist, vor Abgabe von dessen verbindlicher Vertragserklärung zur Honorarvereinbarung in Textform darauf hinzuweisen, dass ein höheres oder niedrigeres Honorar als die in den Honorartafeln dieser Verordnung enthaltenen Werte vereinbart werden kann. Erfolgt der Hinweis nach Satz 1 nicht oder nicht rechtzeitig, gilt für die zwischen den Vertragsparteien vereinbarten Grundleistungen anstelle eines höheren Honorars ein Honorar in Höhe des jeweiligen Basishonorarsatzes als vereinbart. — printed p.8', verification_note='md-verified 2026-09-05 (§7 Abs.2, printed p.8) [VC]', verified_at=now() where id='824e8dc6-323b-4cad-90ed-29bac9175eb5' and verification_status not in ('verified_against_standard','corrected');

