-- HOAI-EQ-01 · H_basis
update public.equations set verification_quote='§ 13 Interpolation Zwischenstufen der in den Honorartafeln angegebenen anrechenbaren Kosten und Flächen oder Verrechnungseinheiten sind durch lineare Interpolation zu ermitteln. | (2) Basishonorarsatz ist der jeweils untere in den Honorartafeln dieser Verordnung enthaltene Honorarsatz. — printed p.9, p.7', verification_note='md-verified 2026-09-05 (§13; §2a Abs.2, printed p.9, p.7) [VC] — the HOAI prints no algebraic formula; it states the rule in words and the encoded expression is EKOWAI’s rendering of it', verified_at=now() where id='2c177fbd-dc96-4ffd-9bb3-e79fc13d70d5' and verification_quote is null;
-- HOAI-EQ-02 · H_oben
update public.equations set verification_quote='§ 13 Interpolation Zwischenstufen der in den Honorartafeln angegebenen anrechenbaren Kosten und Flächen oder Verrechnungseinheiten sind durch lineare Interpolation zu ermitteln. | (1) Die Honorartafeln dieser Verordnung w eisen Orientierungswerte aus, die an der Art und dem Umfang der Aufgabe sowie an der Leistung ausgerichtet sind. Die Honorartafeln enthalten für jeden Leistungsbereich Honorarspannen vom Basishonorarsatz bis zum oberen Honorarsatz, gegliedert nach den — printed p.9, p.6', verification_note='md-verified 2026-09-05 (§13; §2a Abs.1, printed p.9, p.6) [VC] — the HOAI prints no algebraic formula; it states the rule in words and the encoded expression is EKOWAI’s rendering of it', verified_at=now() where id='86a93a1d-a7bf-4ef9-8ebc-584e3f3049cf' and verification_quote is null;
-- HOAI-EQ-03 · H_tafel
update public.equations set verification_quote='(1) Die Honorartafeln dieser Verordnung w eisen Orientierungswerte aus, die an der Art und dem Umfang der Aufgabe sowie an der Leistung ausgerichtet sind. Die Honorartafeln enthalten für jeden Leistungsbereich Honorarspannen vom Basishonorarsatz bis zum oberen Honorarsatz, gegliedert nach den | (1) Das Honorar richtet sich nach der Vereinbarung, die die Vertragsparteien in Textform treffen. Sofern keine Vereinbarung über die Höhe des Honorars in Textform getroffen wurde, gilt für Grundleistungen der jeweilige Basishonorarsatz als vereinbart, der sich bei der Anwendung der Honorargrundlagen des § 6 ergibt. — printed p.6, p.8', verification_note='md-verified 2026-09-05 (§2a Abs.1; §7 Abs.1, printed p.6, p.8) [VC] — the HOAI prints no algebraic formula; it states the rule in words and the encoded expression is EKOWAI’s rendering of it; the Honorartafel values are Orientierungswerte, so s_satz may lawfully leave [0,1]', verified_at=now() where id='e29beb8e-62b0-4422-8035-5e46f28ed598' and verification_quote is null;
-- HOAI-EQ-04 · H_phasen
update public.equations set verification_quote='(1) Werden dem Auftragnehmer nicht alle Leistungsphasen eines Leistungsbildes übertragen, so dürfen nur die für die übertragenen Phasen vorgesehenen Prozentsätze berechnet und vereinbart werden. Die Vereinbarung hat in Textform zu erfolgen. — printed p.8', verification_note='md-verified 2026-09-05 (§8 Abs.1, printed p.8) [VC] — the HOAI prints no algebraic formula; it states the rule in words and the encoded expression is EKOWAI’s rendering of it', verified_at=now() where id='21fd5fb6-c76a-4afa-98d9-31a8d1c190d0' and verification_quote is null;
-- HOAI-EQ-05 · H_zuschlag
update public.equations set verification_quote='5. dem Umbau- oder Modernisierungszuschlag auf das Honorar. Der Umbau- oder Modernisierungszuschlag ist unter Berücksichtigung des Schwierigkeitsgrads der Leistungen in Textform zu vereinbaren. Die Höhe des Zuschlags auf das Honorar ist in den jeweiligen Honorarregelungen der Leistungsbilder der Teile 3 und 4 und in Anlage 1 Nummer 1.2 geregelt. Sofern keine Vereinbarung in Textform getroffen wurde, gilt ein Zuschlag von 20 Prozent ab einem durchschnittlichen Schwierigkeitsgrad als vereinbart. — printed p.8', verification_note='md-verified 2026-09-05 (§6 Abs.2, printed p.8) [VC] — the HOAI prints no algebraic formula; it states the rule in words and the encoded expression is EKOWAI’s rendering of it', verified_at=now() where id='42c36e85-fbee-4876-82ff-191503e660dc' and verification_quote is null;
-- HOAI-EQ-06 · H_gesamt
update public.equations set verification_quote='(1) Der Auftragnehmer kann neben den Honoraren dieser Verordnung auch die für die Ausführung des Auftrags erforderlichen Nebenkosten in Rechnung stellen; ausgenommen sind die abziehbaren Vorsteuern gemäß § 15 | (1) Der Auftragnehmer hat Anspruch auf Ersatz der gesetzlich geschuldeten Umsatzsteuer für nach dieser Verordnung abrechenbare Leistungen, sofern nicht die Kleinunternehmerregelung nach § 19 des — printed p.9, p.10', verification_note='md-verified 2026-09-05 (§14 Abs.1; §16 Abs.1, printed p.9, p.10) [VC] — the HOAI prints no algebraic formula; it states the rule in words and the encoded expression is EKOWAI’s rendering of it', verified_at=now() where id='b3637322-8489-4492-9fb2-0bdb89cdcfa4' and verification_quote is null;
